// This code should be placed in an n8n Function node

// Get the input items
const items = $input.all();

// Process each item in the array
return items.map(item => {
  // Create a new value for the count field
  let newCount = 1;

  // If there's an existing counter value, use it as a base
  if (item.json && item.json.counter !== undefined) {
    newCount = item.json.counter + 1;
  }

  // Ensure json property exists
  if (!item.json) {
    item.json = {};
  }

  // Set the value to the new field name "count"
  item.json.count = newCount;

  // Return the modified item
  return item;
});

// This approach handles both single tweets and collections
// It focuses on properly formatting the output for n8n
// First, let's log what we're working with for debugging
console.log("Input item structure:", JSON.stringify($input.item, null, 2));

// Function to format the date in a more human-readable way
function formatDate(dateString) {
  if (!dateString) return '';

  try {
    const date = new Date(dateString);
    // Format: "March 13, 2025 at 19:25"
    return date.toLocaleString('en-US', {
      year: 'numeric',
      month: 'long',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  } catch (error) {
    console.log("Error formatting date:", error);
    return dateString; // Return original if parsing fails
  }
}

// Check if this is a Twitter Search result with multiple tweets
if ($input.item.json.tweets && Array.isArray($input.item.json.tweets) && $input.item.json.tweets.length > 0) {
  // This is a collection of tweets
  // In n8n, to output multiple items, we need to use an array of objects with a json property
  const items = $input.item.json.tweets.map(tweet => {
    return {
      json: {
        tweetId: tweet.id || '',
        url: tweet.url || '',
        content: tweet.text || '',
        likeCount: tweet.likeCount || 0,
        retweetCount: tweet.retweetCount || 0,
        replyCount: tweet.replyCount || 0,
        quoteCount: tweet.quoteCount || 0,
        viewCount: tweet.viewCount || 0,
        createdAt: formatDate(tweet.createdAt)
      }
    };
  });

  console.log(`Processing ${items.length} tweets`);

  // Return all items
  return items;
} else {
  // This is a single tweet, just extract and return its data
  const tweetData = {
    tweetId: $input.item.json.id || '',
    url: $input.item.json.url || '',
    content: $input.item.json.text || '',
    likeCount: $input.item.json.likeCount || 0,
    retweetCount: $input.item.json.retweetCount || 0,
    replyCount: $input.item.json.replyCount || 0,
    quoteCount: $input.item.json.quoteCount || 0,
    viewCount: $input.item.json.viewCount || 0,
    createdAt: formatDate($input.item.json.createdAt)
  };

  console.log("Processing single tweet");

  // Return as a single item
  return {
    json: tweetData
  };
}

// Tüm tweetleri toplayacağımız boş ana liste
let allTweets = [];

// Döngümüz 3 kere çalıştığı için (Run 0, 1, 2)
for (let i = 0; i < 3; i++) {
  // 'Extract Info' düğümünün o anki turundan verileri çek
  // Not: Eğer düğümünün adı farklıysa buradaki "Extract Info" ismini güncelle
  let runData = $items("Extract Info", 0, i);

  if (runData && runData.length > 0) {
    // Gelen 20'lik veriyi ana listemize ekle
    allTweets = allTweets.concat(runData);
  }
}

// Artık elimizde 3 parça değil, 60 tweetlik tek bir devasa paket var
return allTweets;

// Gelen 60 tweeti alıyoruz
const items = $input.all();

// Sadece ID ve Text kısımlarını alıp hafif bir liste yapıyoruz (Token tasarrufu için)
const simplifiedTweets = items.map(item => {
  return {
    id: item.json.tweetId,
    text: item.json.content
  };
});

// AI'a göndermek üzere tek bir JSON objesi olarak paketliyoruz
return [{
  json: {
    ai_input: JSON.stringify(simplifiedTweets, null, 2),
    original_data: items // Orijinal veriyi saklıyoruz ki onaylananları geri çağırabilelim
  }
}];

// 1. AI'dan gelen ham metni (text) yakalayalım
const inputData = $input.item.json;
let rawContent = "";

if (typeof inputData.text === 'string') {
  rawContent = inputData.text;
} else if (inputData.message && inputData.message.content) {
  rawContent = inputData.message.content;
} else {
  // N8n veriyi nerede saklarsa saklasın, tümünü metne çevir
  rawContent = JSON.stringify(inputData);
}

let approvedIds = [];

// 2. KESİN ÇÖZÜM (Regex - Düzenli İfadeler):
// AI'ın çıktısı ne kadar bozuk olursa olsun, içindeki 18-20 haneli Twitter ID'lerini zorla söküp alıyoruz.
const idRegex = /"(\d{18,20})"/g;
let match;
while ((match = idRegex.exec(rawContent)) !== null) {
  approvedIds.push(match[1]);
}

// Alternatif: Bazen AI tırnaksız da verebilir, onları da yakalayalım
if (approvedIds.length === 0) {
  const fallbackRegex = /\b(\d{18,20})\b/g;
  while ((match = fallbackRegex.exec(rawContent)) !== null) {
    approvedIds.push(match[1]);
  }
}

// Aynı ID iki kere geldiyse tekilleştir (Deduplicate)
approvedIds = [...new Set(approvedIds)];

// EKRANA YAZDIR: Ne bulduğumuzu görelim
console.log("AI'ın Onayladığı ID'ler: ", approvedIds);

// 3. Orijinal verileri bir önceki paketleme düğümünden çekiyoruz
// NOT: Adı 'Code in JavaScript1' değilse burayı kendi düğüm adına göre değiştir!
const originalItems = $('Deduplication Gate').item.json.original_data;

if (!originalItems || !Array.isArray(originalItems)) {
  throw new Error("Orijinal veriler (original_data) bulunamadı! 'Code in JavaScript1' ismini kontrol et.");
}

// 4. Safkan skandalları ayıklıyoruz (GİYOTİN İNİYOR)
const finalApprovedTweets = originalItems.filter(item => {
  return approvedIds.includes(item.json.tweetId);
});

// Eğer AI hiçbir şeyi beğenmediyse boş dönmesin, uyarı versin
if (finalApprovedTweets.length === 0) {
  return [{ json: { warning: "AI bu 60 tweetin hiçbirini yeterince skandal bulmadı! (Sıfır onay)" } }];
}

// 5. Şampiyonları sonrakı adıma yolla
return finalApprovedTweets;

// 1. Notion'dan gelen verileri alalım ve KESİN METNE çevirelim
const notionItems = $input.all();
let pastIds = [];

notionItems.forEach(item => {
  if (item.json && item.json.property_source_id) {
    // ID'yi zorla String yap ve sağındaki solundaki görünmez boşlukları (trim) sil
    pastIds.push(String(item.json.property_source_id).trim());
  }
});

// DEBUG: Sistemi röntgenleyelim (Browser konsoluna veya n8n loglarına yazar)
console.log("NOTION'DAN OKUNAN GEÇMİŞ ID'LER:", pastIds);

// 2. '60=1' düğümünden gelen 60 tweeti her formata dayanıklı şekilde çağıralım
let allTweets = [];
const node60 = $('60=1').all();

if (node60.length === 1 && node60[0].json && node60[0].json.original_data) {
    allTweets = node60[0].json.original_data;
} else if (node60.length === 1 && Array.isArray(node60[0].json)) {
    allTweets = node60[0].json;
} else {
    allTweets = node60;
}

// 3. DEDUPLICATION (Kusursuz Giyotin)
const freshTweets = allTweets.filter(item => {
  // Tweet ID'yi güvenli bir şekilde bul, metne çevir ve boşlukları sil
  let rawId = item.json ? item.json.tweetId : item.tweetId;
  if (!rawId) return true; // Hata koruması

  let cleanTweetId = String(rawId).trim();

  // Bu temizlenmiş ID, Notion listemizde var mı?
  let isOld = pastIds.includes(cleanTweetId);

  // TEST TAKİBİ: Sahte eklediğin ID sistemden geçerken dedektiflik yapalım
  if (cleanTweetId === "2044052981675327825") {
      console.log(`🕵️ TEST ID YAKALANDU! Notion listesinde bulundu mu? -> ${isOld}`);
  }

  // SADECE eski DEĞİLSE listeye al (Eskiyse false döner ve çöpe gider)
  return !isOld;
});

// 4. Eğer hepsi eski çıktıysa
if (freshTweets.length === 0) {
  return [{ json: { warning: "Gelen 60 tweetin hepsi eski! Ajan 2'ye gidecek taze veri yok." } }];
}

// 5. Kalan TAZE tweetleri Gardiyan için paketle
const simplifiedTweets = freshTweets.map(item => {
  let itemData = item.json ? item.json : item;
  return {
    id: itemData.tweetId,
    text: itemData.content
  };
});

// Son çıkış
return [{
  json: {
    ai_input: JSON.stringify(simplifiedTweets, null, 2),
    original_data: freshTweets
  }
}];

const inputJson = $input.item.json;
let parsedAi = {};

try {
    let aiText = "";

    // n8n'in bazen derinlere sakladığı o metni bulalım
    if (inputJson.output && Array.isArray(inputJson.output) && inputJson.output.length > 0) {
        aiText = inputJson.output[0].content[0].text;
    } else {
        aiText = inputJson.text || inputJson.message?.content || inputJson.output || "";
    }

    // Markdown (```json) kalıntılarını temizle ve JSON'a çevir
    let cleanText = aiText.replace(/```json/gi, '').replace(/```/gi, '').trim();
    parsedAi = JSON.parse(cleanText);

} catch (e) {
    throw new Error("Skandal Ajanı verisi JSON'a çevrilemedi: " + e.message);
}

// --- TWEET AVCI MANTIK (TWITTER HUNTER) ---
// GPT'nin twitter_postu yerine uydurabileceği tüm varyasyonları tarayalım
let gelen_tweet = "";
for (const key in parsedAi) {
  const k = key.toLowerCase();
  if (k.includes("twitter") || k.includes("tweet") || k.includes("x_post")) {
    if(parsedAi[key] && typeof parsedAi[key] === 'string') {
       gelen_tweet = parsedAi[key];
       break; 
    }
  }
}
// Eğer döngü bulamazsa varsayılan anahtara bak, o da yoksa hata mesajı yaz
gelen_tweet = gelen_tweet || parsedAi.twitter_postu || "HATA: Twitter içeriği üretilemedi.";

// Şampiyon Tweet'in ID'sini Limit düğümünden çekelim
let sourceTweetId = $('Limit1').first().json.tweetId;

// Notion için her şeyi altın tepside sunalım
return [{
    json: {
        kanca: parsedAi.kanca || parsedAi.Kanca || "HATA: Kanca Bulunamadı",
        senaryo: parsedAi.senaryo || parsedAi.Senaryo || "HATA: Senaryo Bulunamadı",
        aciklama: parsedAi.aciklama || parsedAi.Aciklama || "HATA: Açıklama Bulunamadı",
        twitter_postu: gelen_tweet, // Yeni mermimiz burada!
        source_id: String(sourceTweetId),
        durum: "🟢 Üretime Hazır"
    }
}];
